INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2015CIV', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'The system of equations $6x + ky = 21$ and $-9x + 6y = c$ has no solution. What is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$-4$"},{"key":"B","text":"$4$"},{"key":"C","text":"$-9$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'A', NULL, E'For a system to have no solution, the lines must be parallel, meaning the ratios of corresponding coefficients are equal but the ratio of constants differs. The proportionality condition is $\\frac{a_1}{a_2} = \\frac{b_1}{b_2} \\neq \\frac{c_1}{c_2}$. Here $a_1 = 6$, $b_1 = k$, and $a_2 = -9$, $b_2 = 6$. Setting $\\frac{6}{-9} = \\frac{k}{6}$ gives $-\\frac{2}{3} = \\frac{k}{6}$, so $k = -4$. The distractor $4$ results from dropping the negative sign when cross-multiplying. The distractor $-9$ confuses the coefficient of $x$ in the second equation with $k$. The distractor $9$ comes from taking the absolute value of the $x$-coefficient in the second equation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20DEUC1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'Researchers wanted to test whether a new ergonomic keyboard reduces wrist strain. They recruited 174 office workers and allowed each participant to choose whether to use the new keyboard or keep their standard keyboard for 8 weeks. At the end of the study, the group using the new keyboard reported 31% less wrist strain on average. Which of the following is the most significant flaw in the study design?', NULL, $lyceon_json$[{"key":"A","text":"The study lasted only 8 weeks, which may not be long enough."},{"key":"B","text":"Participants were not randomly assigned to the keyboard groups, so confounding variables may explain the difference."},{"key":"C","text":"The sample size of 174 is too small to detect any difference."},{"key":"D","text":"The study should have included a third group using a different ergonomic keyboard."}]$lyceon_json$::jsonb, 'B', NULL, E'The critical flaw is that participants self-selected into groups rather than being randomly assigned. Workers who chose the ergonomic keyboard may differ systematically from those who kept their standard keyboard (e.g., in ergonomic awareness, typing habits, or preexisting wrist conditions), creating confounding variables that could explain the observed difference. While study duration is a practical consideration, it is not the primary design flaw. A sample of 174 is not inherently too small for a two-group comparison. Adding a third keyboard group would not address the fundamental issue of self-selection bias.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20IB2WT', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'Two parallel lines are cut by a transversal. One of the angles formed measures $137°$. A triangle is formed by the transversal and segments of the two parallel lines, where the angle at one vertex on a parallel line is the supplement of the $137°$ angle. If a second angle of this triangle measures $29°$, what is the measure of the third angle of the triangle?', NULL, $lyceon_json$[{"key":"A","text":"$14°$"},{"key":"B","text":"$108°$"},{"key":"C","text":"$151°$"},{"key":"D","text":"$43°$"}]$lyceon_json$::jsonb, 'B', NULL, E'The supplement of $137°$ is $180° - 137° = 43°$. The triangle has angles $43°$, $29°$, and a third angle. Using the triangle angle sum: third angle $= 180° - 43° - 29° = 108°$. The value $14°$ results from subtracting $29°$ from $43°$ rather than using the triangle angle sum, reflecting partial reasoning. The value $151°$ comes from subtracting only $29°$ from $180°$, forgetting to also subtract the $43°$ angle, a concept gap about angle sums. The value $43°$ results from stopping at the supplement calculation and mistakenly reporting it as the answer, reflecting an equation setup error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21EKDH0', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In right triangle $JKL$, angle $L = 90°$ and $\\sin(J) = \\frac{2}{7}$. What is the value of $\\cos(J)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{3\\sqrt{5}}{7}$"},{"key":"B","text":"$\\frac{5}{7}$"},{"key":"C","text":"$\\frac{2}{5}$"},{"key":"D","text":"$\\frac{45}{49}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Since $\\sin(J) = \\frac{2}{7}$, using the Pythagorean identity $\\cos^2(J) = 1 - \\sin^2(J) = 1 - \\frac{4}{49} = \\frac{45}{49}$, so $\\cos(J) = \\frac{\\sqrt{45}}{7} = \\frac{3\\sqrt{5}}{7}$. The value $\\frac{5}{7}$ results from an arithmetic slip, computing $7 - 2 = 5$ instead of using the Pythagorean identity properly. The value $\\frac{2}{5}$ comes from partial reasoning, incorrectly forming a tangent-like ratio instead of cosine. The value $\\frac{45}{49}$ is $\\cos^2(J)$ rather than $\\cos(J)$, reflecting a concept gap about forgetting to take the square root after applying the Pythagorean identity.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21SWADW', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'grid_in', E'A line is perpendicular to $5x - 3y = 17$ and passes through the point $(7, -2)$. What is the $x$-intercept of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11/3', ARRAY['11/3', '3.666', '3.667'], E'Rewriting $5x - 3y = 17$ in slope-intercept form gives $y = \\frac{5}{3}x - \\frac{17}{3}$, so the slope of this line is $\\frac{5}{3}$. A line perpendicular to it has slope $-\\frac{3}{5}$. Using point-slope form with $(7, -2)$: $y + 2 = -\\frac{3}{5}(x - 7)$. Distributing gives $y + 2 = -\\frac{3}{5}x + \\frac{21}{5}$, so $y = -\\frac{3}{5}x + \\frac{11}{5}$. Setting $y = 0$ to find the $x$-intercept: $0 = -\\frac{3}{5}x + \\frac{11}{5}$, which gives $\\frac{3}{5}x = \\frac{11}{5}$, so $x = \\frac{11}{3}$. A common sign error is using the slope $\\frac{3}{5}$ (the ordinary reciprocal without negating) for the perpendicular line, which would yield a different intercept. Another error is confusing the perpendicular slope with $-\\frac{5}{3}$ (negating without reciprocating), which also produces a wrong answer.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22064E1', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $g(x) = 3 \\cdot 2^x$ is defined for all real numbers. When $x$ increases by $4$, how does the value of $g(x)$ change?', NULL, $lyceon_json$[{"key":"A","text":"It is multiplied by $8$."},{"key":"B","text":"It is increased by $48$."},{"key":"C","text":"It is multiplied by $16$."},{"key":"D","text":"It is increased by $16$."}]$lyceon_json$::jsonb, 'C', NULL, E'Evaluating $g(x + 4) = 3 \\cdot 2^{x+4} = 3 \\cdot 2^x \\cdot 2^4 = 16 \\cdot g(x)$. So when $x$ increases by $4$, the function value is multiplied by $16$. Getting multiplied by $8$ results from computing $2^3$ instead of $2^4$. Getting increased by $48$ comes from incorrectly treating the change as additive and computing $3 \\cdot 4 \\cdot 4 = 48$. Getting increased by $16$ confuses multiplicative exponential growth with additive change.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM226RPW7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A commercial printer prints $47$ pages per minute. Each page uses $0.03$ fluid ounces of ink. Ink is sold in cartridges containing $11$ fluid ounces each. What is the minimum number of cartridges needed to print a document that takes $2$ hours and $37$ minutes to print?', NULL, $lyceon_json$[{"key":"A","text":"$19$"},{"key":"B","text":"$20$"},{"key":"C","text":"$21$"},{"key":"D","text":"$31$"}]$lyceon_json$::jsonb, 'C', NULL, E'The total printing time is $2 \\times 60 + 37 = 157$ minutes. The total pages printed are $47 \\times 157 = 7{,}379$. The total ink used is $7{,}379 \\times 0.03 = 221.37$ fluid ounces. Dividing by $11$ fluid ounces per cartridge gives $\\frac{221.37}{11} \\approx 20.12$, so $21$ cartridges are needed since a partial cartridge still requires purchasing a full one. The value $19$ results from misinterpreting 2 hours and 37 minutes as $2.37$ hours ($142.2$ minutes), yielding fewer total pages. The value $20$ comes from rounding $20.12$ down instead of up, ignoring that a partial cartridge must still be purchased. The value $31$ results from treating 2 hours and 37 minutes as $237$ minutes instead of $157$ minutes.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"unit_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22RVU02', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $52°$ and the measure of angle $Q$ is $73°$. What is the measure, in degrees, of angle $R$?', NULL, $lyceon_json$[{"key":"A","text":"$55°$"},{"key":"B","text":"$125°$"},{"key":"C","text":"$45°$"},{"key":"D","text":"$65°$"}]$lyceon_json$::jsonb, 'A', NULL, E'The sum of the interior angles of a triangle is $180°$. Therefore, angle $R = 180° - 52° - 73° = 55°$. The value $125°$ results from adding $52° + 73°$ instead of subtracting from $180°$, which reflects a misunderstanding of the angle sum property. The value $45°$ results from an arithmetic slip such as computing $180 - 52 - 73$ as $180 - 135 = 45$ by miscalculating the subtraction. The value $65°$ comes from subtracting only one angle: $180° - 52° = 128°$, then making an error to arrive at $65°$, or from confusing the given angle measures.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23YBTUL', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'A shipping company offers two container sizes. Small containers hold 11 pounds and large containers hold 29 pounds. A shipment must weigh more than 200 pounds but no more than 377 pounds. If exactly 7 small containers are used, what is the greatest number of large containers that can be included in the shipment?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '10', ARRAY['10'], E'With 7 small containers, the weight from small containers is $7 \\times 11 = 77$ pounds. Let $n$ be the number of large containers. The total weight is $77 + 29n$. The constraint that the shipment weighs no more than 377 pounds gives $77 + 29n \\leq 377$, so $29n \\leq 300$, meaning $n \\leq \\frac{300}{29} \\approx 10.34$. Since $n$ must be a whole number, the maximum is $n = 10$. We verify the lower bound: $77 + 29(10) = 367 > 200$, which satisfies the minimum weight requirement.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25C22SN', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'A plumber charges a flat fee of $38$ dollars for a house call plus $19$ dollars for each hour of labor. If the total charge for a job was $133$ dollars, how many hours of labor were required?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$7$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting up the equation $19h + 38 = 133$ and subtracting $38$ from both sides gives $19h = 95$. Dividing by $19$ yields $h = 5$. The value $3$ results from swapping the flat fee and hourly rate, solving $38h + 19 = 133$ instead. The value $7$ comes from dividing the total $133$ by $19$ without first subtracting the flat fee, which ignores part of the equation. The value $9$ results from adding the flat fee instead of subtracting it: $(133 + 38) \\div 19 = 9$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25V4ER3', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'A surveyor stands at point $A$ and measures the angle of elevation to the top of a building at point $B$ to be $53°$. She then walks $40$ meters directly toward the building to point $C$, where the angle of elevation to the top is $71°$. What is the height of the building, in meters, rounded to the nearest whole number? (Use $\\tan(53°) \\approx 1.327$ and $\\tan(71°) \\approx 2.904$.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '98', ARRAY['98'], E'Let $h$ be the height of the building and $d$ be the horizontal distance from point $C$ to the base of the building. From point $C$: $\\tan(71°) = \\frac{h}{d}$, so $h = 2.904d$. From point $A$: $\\tan(53°) = \\frac{h}{d + 40}$, so $h = 1.327(d + 40)$. Setting equal: $2.904d = 1.327d + 53.08$. Then $1.577d = 53.08$, so $d \\approx 33.659$. Therefore $h = 2.904 \\times 33.659 \\approx 97.7$, which rounds to $98$ meters. This problem requires setting up two trigonometric equations with two unknowns and solving the resulting system.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27GYZIB', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $7x^3 - 21x^2 + 14x$?', NULL, $lyceon_json$[{"key":"A","text":"$7x(x^2 - 3x + 2)$"},{"key":"B","text":"$7x(x^2 - 3x - 2)$"},{"key":"C","text":"$7(x^3 - 3x + 2)$"},{"key":"D","text":"$x(7x^2 - 21x)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Each term in $7x^3 - 21x^2 + 14x$ shares a greatest common factor of $7x$. Dividing each term by $7x$ gives $x^2 - 3x + 2$, so the expression factors as $7x(x^2 - 3x + 2)$. The expression $7x(x^2 - 3x - 2)$ results from incorrectly negating the constant term when factoring. The expression $7(x^3 - 3x + 2)$ fails to factor out $x$ and incorrectly simplifies the middle term. The expression $x(7x^2 - 21x)$ only partially factors and drops the $+14x$ term entirely.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28T28XD', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $3x + 7y = 42$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, -6)$"},{"key":"B","text":"$(0, 6)$"},{"key":"C","text":"$(0, 14)$"},{"key":"D","text":"$(14, 0)$"}]$lyceon_json$::jsonb, 'B', NULL, E'The $y$-intercept occurs where $x = 0$. Substituting $x = 0$ into $3(0) + 7y = 42$ gives $7y = 42$, so $y = 6$. The $y$-intercept is $(0, 6)$. The point $(0, -6)$ reflects a sign error in the final step. The point $(0, 14)$ comes from dividing $42$ by $3$ instead of by $7$, confusing the coefficients. The point $(14, 0)$ is the $x$-intercept, not the $y$-intercept, resulting from setting $y = 0$ instead of $x = 0$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM297UZWN', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A linear function $h$ satisfies $h(2) = 13$ and $h(9) = 48$. What is the value of $h(6)$?', NULL, $lyceon_json$[{"key":"A","text":"$28$"},{"key":"B","text":"$30$"},{"key":"C","text":"$33$"},{"key":"D","text":"$43$"}]$lyceon_json$::jsonb, 'C', NULL, E'The slope of $h$ is $\\frac{48 - 13}{9 - 2} = \\frac{35}{7} = 5$. Using point-slope form with $(2, 13)$: $h(x) = 5(x - 2) + 13 = 5x + 3$. Therefore $h(6) = 5(6) + 3 = 33$. The value $28$ results from an equation setup error such as computing $5 \\cdot 6 - 2 = 28$, incorrectly treating the input value $2$ as the $y$-intercept. The value $30$ comes from computing $5 \\cdot 6 = 30$ but omitting the constant term, reflecting partial reasoning that stops after applying the slope. The value $43$ comes from using $h(2) = 13$ as the $y$-intercept directly, computing $5 \\cdot 6 + 13 = 43$, which is a concept gap about the distinction between a function value at a point and the $y$-intercept.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29RWCGI', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A community theater needs at least 340 tickets sold across two performances. The first performance sold $f$ tickets and the second sold $s$ tickets, where each ticket for the second performance costs 23 dollars, and the theater requires revenue from the second performance to be more than 529 dollars. Which system of inequalities models these constraints?', NULL, $lyceon_json$[{"key":"A","text":"$f + s \\geq 340$ and $23s > 529$"},{"key":"B","text":"$f + s > 340$ and $23s \\geq 529$"},{"key":"C","text":"$f + s \\geq 340$ and $23s \\geq 529$"},{"key":"D","text":"$f + s \\leq 340$ and $23s > 529$"}]$lyceon_json$::jsonb, 'A', NULL, E'''At least 340 tickets'' means $f + s \\geq 340$, and ''more than 529 dollars'' in revenue means $23s > 529$. The distractor using $f + s > 340$ and $23s \\geq 529$ swaps the strict and non-strict inequalities, mismatching ''at least'' (which includes equality) and ''more than'' (which excludes equality). The distractor using $\\geq$ for both misreads ''more than'' as ''at least.'' The distractor using $f + s \\leq 340$ reverses the ticket requirement, capping rather than requiring a minimum.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A5AUFM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A dataset of $8$ values has a mean of $37$. A ninth value of $64$ is added to the dataset. What is the mean of the new dataset?', NULL, $lyceon_json$[{"key":"A","text":"$40$"},{"key":"B","text":"$44$"},{"key":"C","text":"$45$"},{"key":"D","text":"$50.5$"}]$lyceon_json$::jsonb, 'A', NULL, E'The original sum is $37 \\times 8 = 296$. Adding $64$ gives a new sum of $296 + 64 = 360$. The new mean is $\\frac{360}{9} = 40$. The value $44$ results from adding $\\frac{64}{8} = 8$ to the old mean, incorrectly dividing the new value by the old count instead of recomputing from total sums. The value $45$ results from dividing the new sum by $8$ instead of $9$: $\\frac{360}{8} = 45$. The value $50.5$ comes from averaging only the old mean and the new value: $\\frac{37 + 64}{2} = 50.5$, ignoring that the original mean represents $8$ values.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ANPHED', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'A town''s population was $8{,}400$ in 2018 and $9{,}702$ in 2023. What is the percent increase in the town''s population from 2018 to 2023?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '15.5', ARRAY['31/2', '15.5'], E'The increase in population is $9{,}702 - 8{,}400 = 1{,}302$. The percent increase is $\\frac{1{,}302}{8{,}400} \\times 100 = 15.5\\%$. The base for percent change is the original value ($8{,}400$), not the new value.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AXYBYW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'At a ceramics studio, 143 pieces were fired in a kiln last month. Of the 61 bowls, 14 cracked during firing. Of the 82 vases, 23 cracked during firing. If a piece is selected at random from those that cracked, what is the probability that it is a vase?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{23}{82}$"},{"key":"B","text":"$\\frac{23}{143}$"},{"key":"C","text":"$\\frac{23}{37}$"},{"key":"D","text":"$\\frac{14}{37}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The total number of cracked pieces is $14 + 23 = 37$. The probability that a randomly selected cracked piece is a vase is $\\frac{23}{37}$. The value $\\frac{23}{82}$ incorrectly uses the total vase count as the denominator, finding the probability a vase cracked rather than conditioning on being cracked. The value $\\frac{23}{143}$ uses the overall total as the denominator, ignoring the condition. The value $\\frac{14}{37}$ gives the probability a cracked piece is a bowl, not a vase.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B9P10Q', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A retailer marks up a product by $40\\%$ over its wholesale cost and then offers a $25\\%$ discount on the marked-up price. If the wholesale cost of the product is $58$ dollars, what is the final selling price, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$60.90$"},{"key":"B","text":"$66.70$"},{"key":"C","text":"$75.40$"},{"key":"D","text":"$81.20$"}]$lyceon_json$::jsonb, 'A', NULL, E'The marked-up price is $58 \\times 1.40 = 81.20$ dollars. Applying the $25\\%$ discount gives $81.20 \\times 0.75 = 60.90$ dollars. The value $66.70$ results from treating the two percentages as additive (a net $15\\%$ increase: $58 \\times 1.15 = 66.70$), which is incorrect because the discount is applied to the marked-up price, not the wholesale cost. The value $75.40$ results from computing $25\\%$ of the markup amount ($23.20 \\times 0.25 = 5.80$) and subtracting from the marked-up cost ($81.20 - 5.80 = 75.40$), rather than taking $25\\%$ of the full marked-up price. The value $81.20$ is the marked-up price before the discount is applied.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C25OSV', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'A bakery sells muffins for 3 dollars each and scones for 5 dollars each. On a particular morning, the bakery sold 23 items and collected 89 dollars. How many muffins were sold?', NULL, $lyceon_json$[{"key":"A","text":"$11$"},{"key":"B","text":"$12$"},{"key":"C","text":"$13$"},{"key":"D","text":"$14$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let $m$ be muffins and $s$ be scones. The system is $m + s = 23$ and $3m + 5s = 89$. From the first equation, $s = 23 - m$. Substituting: $3m + 5(23 - m) = 89$, which gives $3m + 115 - 5m = 89$, so $-2m = -26$ and $m = 13$. Then $s = 10$, and we verify: $3(13) + 5(10) = 39 + 50 = 89$. The distractor 11 arises from a subtraction error when simplifying. The distractor 12 results from an arithmetic slip in combining like terms. The distractor 14 comes from setting up the revenue equation incorrectly, such as swapping the prices.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CLTUIF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $17$ units. What is the area of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$34\\pi$"},{"key":"B","text":"$289\\pi$"},{"key":"C","text":"$17\\pi$"},{"key":"D","text":"$68\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a circle is $A = \\pi r^2 = \\pi(17)^2 = 289\\pi$. The value $34\\pi$ results from computing $2\\pi r$ (circumference) instead of $\\pi r^2$, a concept gap between area and circumference formulas. The value $17\\pi$ comes from computing $\\pi r$ without squaring the radius, reflecting partial reasoning. The value $68\\pi$ results from computing $4\\pi r$ through an incorrect formula setup.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DR85A9', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular garden has a length of $17$ feet and a width of $9$ feet. What is the area, in square feet, of the garden?', NULL, $lyceon_json$[{"key":"A","text":"$153$"},{"key":"B","text":"$52$"},{"key":"C","text":"$26$"},{"key":"D","text":"$162$"}]$lyceon_json$::jsonb, 'A', NULL, E'The area of a rectangle is length times width: $17 \\times 9 = 153$ square feet. The value $52$ results from computing the perimeter $2(17 + 9) = 52$ instead of the area, reflecting a concept gap between area and perimeter. The value $26$ computes $17 + 9 = 26$ (half the perimeter), reflecting an equation setup error. The value $162$ results from an arithmetic slip, such as computing $18 \\times 9$ instead of $17 \\times 9$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ETJOKN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A school district compared standardized test scores of students who voluntarily enrolled in an after-school tutoring program with scores of students who did not enroll. The district found that students in the tutoring program scored higher on average. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The tutoring program caused the higher test scores."},{"key":"B","text":"There is an association between enrolling in the tutoring program and higher test scores."},{"key":"C","text":"Students who did not enroll would have scored higher if they had enrolled."},{"key":"D","text":"The tutoring program is equally effective for all students in the district."}]$lyceon_json$::jsonb, 'B', NULL, E'Because students voluntarily enrolled, this is an observational study, not an experiment with random assignment. Observational studies can identify associations but cannot establish causation. Confounding variables (such as motivation or prior achievement) may explain the difference. Claiming the program caused the higher scores requires a randomized experiment. Stating that non-enrolled students would have scored higher if enrolled assumes a causal effect not supported by the design. Claiming equal effectiveness for all students goes beyond what any single comparison can show.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FJKSDN', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'In the figure, triangle $ABC$ has angle $A = 34°$. Point $D$ lies on side $BC$ such that $AD$ bisects angle $A$. If angle $ABD = 73°$, what is the measure, in degrees, of angle $ADB$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '90', ARRAY['90'], E'Since $AD$ bisects angle $A = 34°$, each half is $17°$. In triangle $ABD$, the angles are $17°$ (angle $BAD$), $73°$ (angle $ABD$), and angle $ADB$. By the triangle angle sum property, angle $ADB = 180° - 17° - 73° = 90°$. This problem requires recognizing that the bisector creates two separate triangles, computing the bisected angle correctly, and then applying the angle sum to the appropriate triangle.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GH8CEJ', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'grid_in', E'The function $f(x) = 13x - 47$ models the temperature, in degrees Fahrenheit, of a chemical solution $x$ minutes after an experiment begins. What is the rate of change of the temperature, in degrees Fahrenheit per minute?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13', ARRAY['13'], E'In the linear function $f(x) = 13x - 47$, the coefficient of $x$ represents the rate of change. Since $f(x)$ gives the temperature in degrees Fahrenheit and $x$ is measured in minutes, the rate of change is $13$ degrees Fahrenheit per minute. A common concept gap is to confuse the constant term $-47$ with the rate of change, but $-47$ represents the initial temperature offset (the $y$-intercept), not the rate. Misreading the question and reporting the value of $f$ at a particular time, rather than the slope, would also yield an incorrect answer.', NULL, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H60RCO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'grid_in', E'A ceramicist uses $37$ grams of glaze for every $4$ tiles she paints. At this rate, how many grams of glaze does she need to paint $28$ tiles?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '259', ARRAY['259'], E'The ratio of glaze to tiles is $\\frac{37}{4}$ grams per tile. For $28$ tiles, the glaze needed is $\\frac{37}{4} \\times 28 = 37 \\times 7 = 259$ grams.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I2JY3X', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'grid_in', E'A function is defined by $f(x) = a \\cdot b^x + c$, where $a$, $b$, and $c$ are positive constants. As $x$ approaches negative infinity, $f(x)$ approaches $7$. If $f(0) = 19$ and $f(1) = 43$, what is the value of $b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'As $x \\to -\\infty$, $b^x \\to 0$ (since $b > 0$ and the function has a horizontal asymptote), so $f(x) \\to a \\cdot 0 + c = c$. Therefore $c = 7$. Using $f(0) = 19$: $a \\cdot b^0 + 7 = 19$, so $a \\cdot 1 + 7 = 19$, giving $a = 12$. Using $f(1) = 43$: $12 \\cdot b + 7 = 43$, so $12b = 36$, giving $b = 3$. The value of $b$ is $3$.', NULL, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IEY2FW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two independent random samples are drawn from the same city''s registered voters. Sample A (n = 500) finds 47% support a transit proposal with a margin of error of 4.5 percentage points. Sample B (n = 1,250) finds 53% support the same proposal with a margin of error of 2.8 percentage points. Which of the following conclusions is best supported?', NULL, $lyceon_json$[{"key":"A","text":"The two samples contradict each other, so neither result is reliable."},{"key":"B","text":"Sample B is more reliable because it has a larger sample size, so the true support is exactly 53%."},{"key":"C","text":"Because the confidence intervals from the two samples overlap, it is plausible that the true level of support falls within both intervals."},{"key":"D","text":"The true proportion must be exactly halfway between the two estimates, at 50%."}]$lyceon_json$::jsonb, 'C', NULL, E'Sample A''s confidence interval is $42.5\\%$ to $51.5\\%$, and Sample B''s is $50.2\\%$ to $55.8\\%$. These intervals overlap in the range $50.2\\%$ to $51.5\\%$, so it is plausible the true proportion lies in both intervals simultaneously. Claiming the samples contradict each other ignores the overlap region. Stating the true value is exactly 53% conflates a larger sample with perfect precision and ignores the margin of error. Averaging the two point estimates to get 50% has no statistical basis and ignores the different precisions of the two estimates.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2INNFDG', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $\\frac{6x^2 - x - 23}{3x + 4}$ can be written in the form $ax + b + \\frac{c}{3x + 4}$, where $a$, $b$, and $c$ are constants, what is the value of $a + b + c$?', NULL, $lyceon_json$[{"key":"A","text":"$-12$"},{"key":"B","text":"$-6$"},{"key":"C","text":"$-1$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'A', NULL, E'Performing polynomial long division: $6x^2 \\div 3x = 2x$. Multiplying $2x(3x + 4) = 6x^2 + 8x$ and subtracting from $6x^2 - x - 23$ gives $-9x - 23$. Next, $-9x \\div 3x = -3$. Multiplying $-3(3x + 4) = -9x - 12$ and subtracting from $-9x - 23$ gives $-11$. So the expression equals $2x - 3 + \\frac{-11}{3x + 4}$, meaning $a = 2$, $b = -3$, $c = -11$, and $a + b + c = -12$. Getting $-6$ results from a sign error on $b$, using $+3$ instead of $-3$. Getting $-1$ comes from computing only $a + b$ and omitting $c$. Getting $10$ results from incorrectly computing the remainder as $+11$ instead of $-11$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JPMBSL', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{9t^4 - 25}{3t^2 + 5}$?', NULL, $lyceon_json$[{"key":"A","text":"$3t^2 + 5$"},{"key":"B","text":"$3t^2 - 5$"},{"key":"C","text":"$9t^4 - 5$"},{"key":"D","text":"$3t - 5$"}]$lyceon_json$::jsonb, 'B', NULL, E'The numerator $9t^4 - 25$ is a difference of squares: $(3t^2)^2 - 5^2 = (3t^2 + 5)(3t^2 - 5)$. Dividing by $3t^2 + 5$ cancels one factor, leaving $3t^2 - 5$. Selecting $3t^2 + 5$ reflects a sign error in choosing which factor remains after cancellation. Selecting $9t^4 - 5$ shows a failure to recognize and apply the difference-of-squares identity. Selecting $3t - 5$ incorrectly takes the square root of each term individually rather than factoring the binomial as a whole.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K92AAE', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f(x) = -2(x - 7)^2 + 11$ is defined for all real numbers. What is the maximum value of $f(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$7$"},{"key":"C","text":"$11$"},{"key":"D","text":"$-11$"}]$lyceon_json$::jsonb, 'C', NULL, E'The function is in vertex form $f(x) = a(x - h)^2 + k$ with $a = -2$, $h = 7$, and $k = 11$. Since $a < 0$, the parabola opens downward and the vertex $(7, 11)$ is the maximum point. The maximum value of $f(x)$ is $11$. Selecting $-7$ confuses the maximum value with the negation of the $x$-coordinate of the vertex. Selecting $7$ gives the $x$-coordinate where the maximum occurs rather than the maximum value itself. Selecting $-11$ applies an incorrect sign change to the $k$ value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KLV3WW', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'What are all solutions to the equation $\\sqrt{5x + 11} - x = 1$?', NULL, $lyceon_json$[{"key":"A","text":"$x = 5$ only"},{"key":"B","text":"$x = -2$ only"},{"key":"C","text":"$x = -2$ and $x = 5$"},{"key":"D","text":"$x = 2$ and $x = 5$"}]$lyceon_json$::jsonb, 'A', NULL, E'Isolating the radical gives $\\sqrt{5x + 11} = x + 1$. Squaring both sides: $5x + 11 = x^2 + 2x + 1$, which simplifies to $x^2 - 3x - 10 = 0$. Factoring: $(x - 5)(x + 2) = 0$, so $x = 5$ or $x = -2$. Checking $x = 5$: $\\sqrt{36} - 5 = 6 - 5 = 1$ is valid. Checking $x = -2$: $\\sqrt{1} - (-2) = 1 + 2 = 3 \\neq 1$, so $x = -2$ is extraneous. The only solution is $x = 5$. Selecting $x = -2$ only reflects choosing the extraneous solution while discarding the valid one. Including both $x = -2$ and $x = 5$ fails to check for extraneous solutions introduced by squaring. Selecting $x = 2$ and $x = 5$ results from an arithmetic error in solving the quadratic.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KV8H11', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'In the system of equations $7x - 4y = 31$ and $3x + 4y = 19$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Adding the two equations eliminates $y$: $(7x - 4y) + (3x + 4y) = 31 + 19$, giving $10x = 50$, so $x = 5$. To verify, substitute $x = 5$ into $3(5) + 4y = 19$, yielding $15 + 4y = 19$, so $4y = 4$ and $y = 1$. Checking in the first equation: $7(5) - 4(1) = 35 - 4 = 31$, which is correct.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L8OE8J', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A right triangular prism has a base that is a right triangle with legs of length $13$ cm and $84$ cm. The height of the prism is $6$ cm. What is the volume, in cubic centimeters, of the prism?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3276', ARRAY['3276'], E'The base of the prism is a right triangle with legs $13$ cm and $84$ cm. The area of this triangle is $\\frac{1}{2}(13)(84) = \\frac{1092}{2} = 546$ square cm. The volume of a prism is base area times height: $V = 546 \\times 6 = 3276$ cubic cm. This requires computing the area of a right triangle (using the legs as base and height) and then multiplying by the prism height, a multi-step calculation with non-standard dimensions.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L9QLRC', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'The system of equations $y = x^2 - 6x + 3$ and $y = 2x - 13$ has exactly one solution $(x, y)$. What is the $y$-coordinate of this solution?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-5', ARRAY['-5'], E'Setting the equations equal: $x^2 - 6x + 3 = 2x - 13$. Rearranging gives $x^2 - 8x + 16 = 0$, which factors as $(x - 4)^2 = 0$, so $x = 4$. Substituting into $y = 2x - 13$ gives $y = 2(4) - 13 = -5$. The system has exactly one solution at $(4, -5)$, confirming the line is tangent to the parabola.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M2UHBE', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'A furniture workshop charges a flat fee of 47 dollars plus 19 dollars per hour for custom work. A customer has a budget of no more than 161 dollars. Which inequality represents all possible numbers of hours, $h$, the customer can afford?', NULL, $lyceon_json$[{"key":"A","text":"$47 + 19h \\leq 161$"},{"key":"B","text":"$47 + 19h \\geq 161$"},{"key":"C","text":"$19 + 47h \\leq 161$"},{"key":"D","text":"$47 + 19h < 161$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is the flat fee of 47 dollars plus 19 dollars per hour, giving $47 + 19h$. Since the customer can spend no more than 161 dollars, the total must be less than or equal to 161, yielding $47 + 19h \\leq 161$. The distractor $47 + 19h \\geq 161$ reverses the inequality direction, misunderstanding ''no more than'' as ''at least.'' The distractor $19 + 47h \\leq 161$ swaps the flat fee and hourly rate. The distractor $47 + 19h < 161$ uses strict inequality, but ''no more than'' includes equality, so $\\leq$ is correct.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M7XEPN', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle in the $xy$-plane has the equation $x^2 + y^2 - 6x + 10y - 2 = 0$. What is the radius of this circle?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$36$"},{"key":"C","text":"$\\sqrt{34}$"},{"key":"D","text":"$34$"}]$lyceon_json$::jsonb, 'A', NULL, E'Complete the square: $(x^2 - 6x + 9) + (y^2 + 10y + 25) = 2 + 9 + 25$, giving $(x - 3)^2 + (y + 5)^2 = 36$. The radius is $\\sqrt{36} = 6$. The value $36$ is $r^2$, not $r$, reflecting a concept gap about reading the standard form. The value $\\sqrt{34}$ results from adding only $9 + 25 = 34$ and forgetting to add the constant $2$ from the right side, reflecting partial reasoning. The value $34$ results from the same partial computation without taking the square root, an arithmetic slip compounded with the previous error.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MGCMSN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A pharmaceutical company conducted a randomized controlled trial with 1,380 participants to test a new anti-inflammatory cream. Participants were randomly assigned to receive either the active cream or an identical-looking placebo cream applied twice daily for 12 weeks. Neither the participants nor the physicians measuring outcomes knew which cream each participant received. At the end of the trial, the group using the active cream showed a statistically significant reduction in inflammation compared to the placebo group. However, the company then marketed the cream to teenagers, a demographic that was not included in the trial (all participants were ages 35 to 70). Which of the following best describes the limitation of applying the trial''s results to teenagers?', NULL, $lyceon_json$[{"key":"A","text":"The trial did not use random assignment, so causation cannot be established."},{"key":"B","text":"The trial was not double-blind, so the placebo effect may account for the results."},{"key":"C","text":"The results may not generalize to teenagers because the sample did not include that age group."},{"key":"D","text":"The 12-week duration was too short for any meaningful conclusion about the cream's effectiveness."}]$lyceon_json$::jsonb, 'C', NULL, E'The trial was well-designed: randomized, double-blind, placebo-controlled, and yielded statistically significant results within its studied population (ages 35 to 70). The limitation is one of generalizability: since no teenagers were included, the results cannot be directly extended to that age group, whose physiology and inflammatory responses may differ. Claiming the trial lacked random assignment contradicts the stated design. Claiming it was not double-blind contradicts the description that neither participants nor physicians knew which cream was administered. While study duration is always a consideration, the question specifically asks about the limitation of applying results to teenagers, which is a generalizability issue.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NO1NH0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'A teacher records test scores for $11$ students: $62, 67, 71, 73, 76, 78, 82, 85, 88, 91, 96$. The teacher decides to replace the lowest score with the mean of all $11$ original scores. What is the positive difference between the original median and the new median?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '1', ARRAY['1'], E'The sum of the $11$ original scores is $62 + 67 + 71 + 73 + 76 + 78 + 82 + 85 + 88 + 91 + 96 = 869$. The mean is $\\frac{869}{11} = 79$. The original sorted list is $62, 67, 71, 73, 76, 78, 82, 85, 88, 91, 96$, so the original median (6th value) is $78$. Replacing $62$ with $79$ and re-sorting gives $67, 71, 73, 76, 78, 79, 82, 85, 88, 91, 96$. The new median (6th value) is $79$. The positive difference is $79 - 78 = 1$.', NULL, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O20L27', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points $(2, 11)$ and $(5, 29)$. Which of the following is the equation of this line?', NULL, $lyceon_json$[{"key":"A","text":"$y = 6x - 1$"},{"key":"B","text":"$y = 6x + 1$"},{"key":"C","text":"$y = -6x + 23$"},{"key":"D","text":"$y = \\frac{1}{6}x + \\frac{31}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $m = \\frac{29 - 11}{5 - 2} = \\frac{18}{3} = 6$. Using point-slope form with the point $(2, 11)$: $y - 11 = 6(x - 2)$, which simplifies to $y = 6x - 12 + 11 = 6x - 1$. The equation $y = 6x + 1$ results from an arithmetic slip when computing $-12 + 11$, getting $+1$ instead of $-1$. The equation $y = -6x + 23$ uses a negated slope, a sign error, which when applied through $(2, 11)$ gives $y - 11 = -6(x - 2)$, yielding $y = -6x + 23$. The equation $y = \\frac{1}{6}x + \\frac{31}{3}$ uses the reciprocal of the slope rather than the slope itself, reflecting a concept gap about the slope formula.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PS8JB6', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the positive difference between the solutions of $x^2 - 11x + 28 = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'Factoring the quadratic: $x^2 - 11x + 28 = (x - 4)(x - 7) = 0$, so $x = 4$ or $x = 7$. The positive difference between these solutions is $7 - 4 = 3$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QL4Q8Z', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A wildlife sanctuary houses 83 reptiles. Of these, 29 are turtles, 37 are lizards, and 17 are snakes. If one reptile is selected at random, what is the probability that it is a lizard?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{29}{83}$"},{"key":"B","text":"$\\frac{37}{83}$"},{"key":"C","text":"$\\frac{17}{83}$"},{"key":"D","text":"$\\frac{37}{54}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The probability of selecting a lizard is the number of lizards divided by the total number of reptiles: $\\frac{37}{83}$. The value $\\frac{29}{83}$ results from selecting the turtle count instead. The value $\\frac{17}{83}$ results from selecting the snake count instead. The value $\\frac{37}{54}$ results from dividing by the number of non-turtle reptiles ($83 - 29 = 54$) instead of the total, using a subset as the denominator.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2REMYU5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A dolphin swims $186$ meters in $12$ seconds. A sea turtle swims $91$ meters in $14$ seconds. How many more meters per second does the dolphin swim than the sea turtle?', NULL, $lyceon_json$[{"key":"A","text":"$6.5$"},{"key":"B","text":"$9$"},{"key":"C","text":"$22$"},{"key":"D","text":"$15.5$"}]$lyceon_json$::jsonb, 'B', NULL, E'The dolphin''s speed is $\\frac{186}{12} = 15.5$ meters per second, and the sea turtle''s speed is $\\frac{91}{14} = 6.5$ meters per second. The difference is $15.5 - 6.5 = 9$ meters per second. The value $6.5$ is only the turtle''s speed, not the difference asked for. The value $22$ results from adding the two speeds instead of subtracting. The value $15.5$ is only the dolphin''s speed without computing the comparison.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S0J6YR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A botanist surveys a random sample of 625 trees in a national forest and finds that 41% show signs of bark beetle damage. The margin of error is 3.9 percentage points at the 95% confidence level. The forest contains 28,750 trees total. Which of the following is the best estimate of the number of trees in the entire forest showing signs of bark beetle damage?', NULL, $lyceon_json$[{"key":"A","text":"Between 10,661 and 12,904"},{"key":"B","text":"Between 256 and 281"},{"key":"C","text":"Between 10,063 and 12,938"},{"key":"D","text":"Exactly 11,788"}]$lyceon_json$::jsonb, 'A', NULL, E'The confidence interval for the proportion is $41\\% \\pm 3.9\\%$, or $37.1\\%$ to $44.9\\%$. Applying this to the population of 28,750 trees: $0.371 \\times 28{,}750 = 10{,}661.25$ and $0.449 \\times 28{,}750 = 12{,}903.75$, giving approximately 10,661 to 12,904 trees. The range 256 to 281 applies the percentages to the sample size of 625 instead of the population. The range 10,063 to 12,938 results from rounding errors in the percentage calculation ($35\\%$ to $45\\%$ instead of $37.1\\%$ to $44.9\\%$). Exactly 11,788 treats the point estimate ($0.41 \\times 28{,}750$) as exact, ignoring the margin of error entirely.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S30949', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'The function $f$ is defined by $f(x) = ax + b$, where $a$ and $b$ are integers. If $f(f(2)) = 4$ and $f(f(5)) = 31$, what is the value of $a + b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Since $f(x) = ax + b$, we have $f(2) = 2a + b$ and $f(f(2)) = a(2a + b) + b = 2a^2 + ab + b$. Similarly, $f(5) = 5a + b$ and $f(f(5)) = a(5a + b) + b = 5a^2 + ab + b$. Setting these equal to the given values: $2a^2 + ab + b = 4$ and $5a^2 + ab + b = 31$. Subtracting the first equation from the second eliminates $ab + b$: $3a^2 = 27$, so $a^2 = 9$, giving $a = 3$ or $a = -3$. If $a = 3$: $2(9) + 3b + b = 4$ gives $18 + 4b = 4$, so $b = -\\frac{14}{4} = -3.5$, which is not an integer. If $a = -3$: $2(9) + (-3)b + b = 4$ gives $18 - 2b = 4$, so $b = 7$. Therefore $a = -3$ and $b = 7$, and $a + b = 4$. A sign error when subtracting the equations could lead to $3a^2 = 35$, which has no integer solution. A partial reasoning error is to forget to check which value of $a$ yields an integer $b$, potentially reporting $a + b$ with $a = 3$ and a non-integer $b$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SDKM9D', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on the age of a car, in years, and its resale value, in thousands of dollars. The line of best fit for the data is $y = -2.8x + 31.4$, where $x$ is the age and $y$ is the resale value in thousands of dollars. Which of the following is the best interpretation of the slope of this line?', NULL, $lyceon_json$[{"key":"A","text":"For each additional year of age, the predicted resale value decreases by $2{,}800$ dollars."},{"key":"B","text":"For each additional year of age, the predicted resale value decreases by $2.8$ dollars."},{"key":"C","text":"A new car has a predicted resale value of $31{,}400$ dollars."},{"key":"D","text":"For each additional year of age, the predicted resale value increases by $2{,}800$ dollars."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of $-2.8$ means that for each additional year of age, the predicted resale value changes by $-2.8$ thousand dollars, which is a decrease of $2{,}800$ dollars. The interpretation stating a decrease of $2.8$ dollars fails to account for the unit being thousands of dollars. The statement about a new car''s value of $31{,}400$ dollars describes the $y$-intercept, not the slope. The interpretation stating an increase of $2{,}800$ dollars reverses the sign of the slope, ignoring that the negative value indicates a decrease.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"unit_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U8LMS3', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A right circular cone has a height of $18$ centimeters and a base radius of $7$ centimeters. What is the volume, in cubic centimeters, of the cone?', NULL, $lyceon_json$[{"key":"A","text":"$294\\pi$"},{"key":"B","text":"$882\\pi$"},{"key":"C","text":"$126\\pi$"},{"key":"D","text":"$252\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'The volume of a cone is $V = \\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(7)^2(18) = \\frac{1}{3}\\pi(49)(18) = \\frac{882\\pi}{3} = 294\\pi$. The value $882\\pi$ results from computing $\\pi r^2 h$ without the $\\frac{1}{3}$ factor, reflecting a concept gap about the cone volume formula versus a cylinder. The value $126\\pi$ comes from computing $\\frac{1}{3}\\pi(7)(18) = 42\\pi$ then tripling by mistake, or equivalently using $r$ instead of $r^2$, an equation setup error. The value $252\\pi$ results from using $\\frac{2}{3}$ instead of $\\frac{1}{3}$, reflecting partial reasoning about the relationship between cone and cylinder volumes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UYH4DB', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'If $7x + 23 = 121$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '14', ARRAY['14'], E'Subtracting $23$ from both sides gives $7x = 98$. Dividing both sides by $7$ gives $x = 14$. A common arithmetic slip would be to compute $121 - 23$ incorrectly, yielding a wrong quotient. Adding $23$ instead of subtracting (a sign error) would produce $7x = 144$, giving a non-integer result. Dividing $121$ directly by $7$ without first subtracting $23$ reflects partial reasoning and yields approximately $17.3$, which is incorrect.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V38QIE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'grid_in', E'The line of best fit for a dataset is $y = 1.9x + 7.3$. The sum of the residuals for three data points $(4, a)$, $(8, 25.1)$, and $(13, 34.9)$ equals $0$. What is the value of $a$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9.4', ARRAY['47/5', '9.4'], E'The predicted value at $x = 4$ is $1.9(4) + 7.3 = 7.6 + 7.3 = 14.9$, so the residual for $(4, a)$ is $a - 14.9$. The predicted value at $x = 8$ is $1.9(8) + 7.3 = 15.2 + 7.3 = 22.5$, so the residual is $25.1 - 22.5 = 2.6$. The predicted value at $x = 13$ is $1.9(13) + 7.3 = 24.7 + 7.3 = 32.0$, so the residual is $34.9 - 32.0 = 2.9$. Setting the sum of residuals equal to $0$ gives $(a - 14.9) + 2.6 + 2.9 = 0$, which simplifies to $a - 9.4 = 0$, so $a = 9.4$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VHXYZ5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'The line of best fit for a scatterplot relating hours of study ($x$) to exam score ($y$) is $y = 5.3x + 41$. According to this model, what is the predicted exam score for a student who studies for $6$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$31.8$"},{"key":"B","text":"$46.3$"},{"key":"C","text":"$72.8$"},{"key":"D","text":"$78.1$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 6$ into the equation gives $y = 5.3(6) + 41 = 31.8 + 41 = 72.8$. The value $31.8$ results from computing only $5.3 \\times 6$ without adding the $y$-intercept. The value $46.3$ results from adding $5.3 + 41 = 46.3$ without multiplying the slope by $x$. The value $78.1$ results from substituting $x = 7$ instead of $x = 6$: $5.3(7) + 41 = 78.1$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WEMJCQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A bookstore sells a journal for $34$ dollars. During a sale, the price is reduced by $15\\%$. What is the sale price, in dollars, of the journal?', NULL, $lyceon_json$[{"key":"A","text":"$5.10$"},{"key":"B","text":"$19$"},{"key":"C","text":"$28.90$"},{"key":"D","text":"$39.10$"}]$lyceon_json$::jsonb, 'C', NULL, E'The discount is $34 \\times 0.15 = 5.10$ dollars. The sale price is $34 - 5.10 = 28.90$ dollars. The value $5.10$ is only the discount amount, not the sale price. The value $19$ results from subtracting $15$ from $34$ as though the percentage were a dollar amount. The value $39.10$ results from adding the discount to the original price instead of subtracting it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XN0MZG', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'What value of $x$ satisfies the equation $$\\frac{3(2x - 7)}{5} - \\frac{x + 11}{3} = x - 9$$ ?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17/2', ARRAY['17/2', '8.5'], E'Multiplying every term by $15$ (the least common multiple of $5$ and $3$) clears the fractions: $9(2x - 7) - 5(x + 11) = 15(x - 9)$. Distributing gives $18x - 63 - 5x - 55 = 15x - 135$. Combining like terms on the left yields $13x - 118 = 15x - 135$. Subtracting $13x$ from both sides gives $-118 = 2x - 135$. Adding $135$ gives $17 = 2x$, so $x = \\frac{17}{2}$. A sign error when distributing the negative into $(x + 11)$ — writing $-5x + 55$ instead of $-5x - 55$ — would yield $13x - 8 = 15x - 135$, giving $x = \\frac{127}{2}$, which is incorrect. An arithmetic slip in combining $-63$ and $-55$ would similarly produce a wrong result.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XVM9BQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 400 subscribers to an online magazine found that 58% preferred reading articles on mobile devices. The margin of error for this estimate is 4.9 percentage points at the 95% confidence level. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly 58% of all subscribers prefer reading on mobile devices."},{"key":"B","text":"It is plausible that between 53.1% and 62.9% of all subscribers prefer reading on mobile devices."},{"key":"C","text":"Between 53.1% and 62.9% of the 400 sampled subscribers prefer reading on mobile devices."},{"key":"D","text":"If another sample of 400 subscribers is taken, exactly 58% will prefer reading on mobile devices."}]$lyceon_json$::jsonb, 'B', NULL, E'The margin of error creates a confidence interval of $58\\% \\pm 4.9\\%$, or $53.1\\%$ to $62.9\\%$, for the population parameter. This means it is plausible that the true proportion of all subscribers who prefer mobile falls within this range. Stating that exactly 58% of all subscribers prefer mobile treats the sample statistic as the exact population value. Applying the interval to the sample rather than the population confuses who the inference is about. Claiming a new sample will yield exactly 58% misunderstands sampling variability.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YC9CSC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A shipping warehouse inspects packages on two conveyor lines. Line P processes 270 packages per day and Line Q processes 180 packages per day. On Line P, 3% of packages are flagged as damaged. On Line Q, 7% of packages are flagged as damaged. A package is selected at random from all packages processed that day. Given that the package was flagged as damaged, what is the probability that it came from Line Q, to the nearest thousandth?', NULL, $lyceon_json$[{"key":"A","text":"$0.400$"},{"key":"B","text":"$0.609$"},{"key":"C","text":"$0.070$"},{"key":"D","text":"$0.500$"}]$lyceon_json$::jsonb, 'B', NULL, E'Line P flags $0.03 \\times 270 = 8.1$ packages on average, and Line Q flags $0.07 \\times 180 = 12.6$ packages. The total flagged is $8.1 + 12.6 = 20.7$. By Bayes'' theorem, the probability a flagged package came from Line Q is $\\frac{12.6}{20.7} \\approx 0.609$. The value $0.400$ comes from using the ratio of line volumes $\\frac{180}{450}$ without accounting for different damage rates. The value $0.070$ is simply the damage rate on Line Q, ignoring the conditioning. The value $0.500$ assumes equal likelihood from each line, disregarding both volume and rate differences.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YEM6RG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a $30°$-$60°$-$90°$ triangle, the side opposite the $30°$ angle has length $11$. What is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$11\\sqrt{3}$"},{"key":"B","text":"$22$"},{"key":"C","text":"$11\\sqrt{2}$"},{"key":"D","text":"$33$"}]$lyceon_json$::jsonb, 'B', NULL, E'In a $30°$-$60°$-$90°$ triangle, the hypotenuse is twice the length of the side opposite the $30°$ angle. Therefore, the hypotenuse is $2 \\times 11 = 22$. The value $11\\sqrt{3}$ is the length of the side opposite the $60°$ angle (the longer leg), not the hypotenuse, reflecting a concept gap about which side corresponds to which ratio. The value $11\\sqrt{2}$ confuses the $30°$-$60°$-$90°$ ratios with those of a $45°$-$45°$-$90°$ triangle. The value $33$ results from multiplying by $3$ instead of $2$, an equation setup error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZJEOYW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'The ages, in years, of $9$ members of a hiking club are listed below.$$18, 22, 27, 29, 31, 35, 39, 44, 52$$What is the median age of the group?', NULL, $lyceon_json$[{"key":"A","text":"$29$"},{"key":"B","text":"$31$"},{"key":"C","text":"$33$"},{"key":"D","text":"$30$"}]$lyceon_json$::jsonb, 'B', NULL, E'With $9$ data values already in ascending order, the median is the $\\frac{9+1}{2} = 5$th value, which is $31$. The value $29$ is the 4th value, one position before the median. The value $33$ is the mean of the dataset ($\\frac{297}{9} = 33$), not the median. The value $30$ results from incorrectly averaging the 4th and 5th values ($\\frac{29+31}{2} = 30$) as though the dataset had an even number of values.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZOHKBL', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'A circle with center $(2, -7)$ passes through the point $(5, -3)$. A line tangent to the circle at the point $(5, -3)$ has slope $m$. What is the value of $m$? Express your answer as a fraction.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-3/4', ARRAY['-3/4', '-0.75', '-.75'], E'The radius from the center $(2, -7)$ to the tangent point $(5, -3)$ has slope $\\frac{-3 - (-7)}{5 - 2} = \\frac{4}{3}$. A tangent line is perpendicular to the radius at the point of tangency, so the tangent slope is the negative reciprocal: $m = -\\frac{3}{4}$. This requires computing the slope of the radius segment and then applying the perpendicularity condition for tangent lines to circles.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20Z78HB', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When the cartographers finally reached the summit of the uncharted plateau in late 2019, they discovered that seasonal monsoon flooding ______ the original trail markers they had placed during their previous expedition two years earlier.', $lyceon_json$[{"key":"A","text":"had obliterated"},{"key":"B","text":"has obliterated"},{"key":"C","text":"obliterates"},{"key":"D","text":"would obliterate"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence establishes two past events: the cartographers reached the summit (simple past) and, before that, the flooding destroyed the trail markers. Because the obliteration occurred prior to the discovery, the past perfect ''had obliterated'' is required to indicate the earlier of two past actions. The present perfect ''has obliterated'' incorrectly links a past event to the present moment, which conflicts with the entirely past-tense narrative anchored in ''late 2019.'' The simple present ''obliterates'' describes a habitual or current action, which does not fit the completed past event described. The conditional ''would obliterate'' implies a hypothetical or uncertain future outcome, contradicting the passage''s indication that the destruction had already occurred by the time of discovery.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21Q34KC', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a research article would most effectively support the student''s claim?', E'A student writing a research paper argues that the traditional distinction between "fine art" and "craft" in Western aesthetics has been systematically used to devalue artistic traditions from non-Western cultures, particularly those in which functional objects—textiles, ceramics, metalwork—carry the same aesthetic intentionality and cultural prestige as painting or sculpture in European traditions.', $lyceon_json$[{"key":"A","text":"\"In Kente weaving communities of the Ashanti region, master weavers undergo apprenticeships lasting seven to eleven years, during which they learn not only technical proficiency but also the symbolic vocabulary of color and pattern that communicates lineage, social status, and spiritual meaning—a level of intentional meaning-making that parallels the iconographic programs of Renaissance altarpieces.\""},{"key":"B","text":"\"The global art market has seen a 340 percent increase in auction prices for contemporary African painting since 2014, suggesting that collectors are increasingly willing to invest in non-Western fine art traditions.\""},{"key":"C","text":"\"Anthropologists have documented that ceramic production in pre-Columbian Mesoamerica served primarily utilitarian purposes, with aesthetic considerations secondary to functional requirements such as heat resistance and water retention.\""},{"key":"D","text":"\"Several major Western museums have recently established dedicated departments for decorative arts, reflecting a growing institutional recognition that craft objects merit serious curatorial attention independent of their cultural origin.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The student claims the fine art/craft distinction devalues non-Western traditions where functional objects carry the same aesthetic intentionality as European fine art. The quotation about Kente weaving directly supports this by demonstrating that a functional textile tradition involves extensive training and intentional symbolic meaning-making comparable to Renaissance painting—exactly the kind of parity the student argues is overlooked. The quotation about rising auction prices for African painting concerns fine art rather than craft traditions, so it does not address the devaluation of functional objects. The quotation about utilitarian ceramics actually undermines the student''s claim by suggesting aesthetic considerations were secondary. The quotation about museum departments for decorative arts addresses institutional change but does not demonstrate that non-Western craft traditions carry aesthetic intentionality equivalent to fine art, which is the specific claim needing support.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22J08N8', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Linguist Tomasz Kielar has demonstrated that speakers of Polish use diminutive suffixes not only to indicate small physical size but also to express emotional closeness or affection toward the referent. A shopkeeper might describe bread as "chlebek" rather than "chleb" to suggest warmth and familiarity with customers. ______ Kielar observed that in formal written Polish, diminutives appear far less frequently, since their connotations of intimacy conflict with the register''s emphasis on objectivity and distance.', $lyceon_json$[{"key":"A","text":"By contrast,"},{"key":"B","text":"Likewise,"},{"key":"C","text":"To illustrate,"},{"key":"D","text":"As a result,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage first establishes that diminutives serve emotional functions in spoken Polish, then contrasts this with the observation that formal written Polish avoids diminutives because intimacy conflicts with objectivity. The transition "By contrast" correctly marks this shift from one context (casual speech) to an opposing one (formal writing). The option "Likewise" signals similarity, but the final sentence describes diminutives being avoided in formal writing, which is the opposite of their frequent use in speech. The option "To illustrate" suggests the final sentence is an example of the preceding claim about emotional closeness, yet the sentence introduces a different setting where diminutives are suppressed, not an additional illustration of their affectionate use. The option "As a result" implies the formal avoidance is caused by the shopkeeper''s behavior, but the passage presents the two registers as independently governed, not causally linked.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22L3RTX', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Marine biologists at the Scripps Institution have hypothesized that the bioluminescent flashes produced by certain deep-sea squid species serve primarily as a predator-confusion mechanism rather than as a means of attracting prey. According to this hypothesis, the sudden burst of light disorients pursuing predators long enough for the squid to execute an escape maneuver, functioning analogously to the ink clouds released by shallow-water cephalopods.', $lyceon_json$[{"key":"A","text":"Deep-sea squid that produce bioluminescent flashes have significantly higher survival rates during predator encounters than closely related non-luminescent species."},{"key":"B","text":"The wavelength of light produced by deep-sea squid bioluminescence closely matches the wavelengths emitted by the squid's preferred prey organisms."},{"key":"C","text":"Deep-sea squid species that produce bioluminescent flashes also possess ink sacs, though they rarely deploy ink at depth."},{"key":"D","text":"Predators of deep-sea squid tend to hunt in waters where ambient light levels are higher than in the squid's typical habitat."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis claims bioluminescent flashes help squid escape predators. A finding that luminescent squid survive predator encounters at higher rates than non-luminescent relatives would directly support this anti-predator function. The finding about wavelength matching the prey''s emissions would support a prey-attraction function, which is the alternative the hypothesis rejects. The finding about possessing ink sacs is tangentially related through the analogy in the passage but does not directly test whether bioluminescence itself deters predators. The finding about predators hunting in higher-light waters does not address whether the squid''s own flashes serve a defensive function.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW238R7KK', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The textile conservator determined that the tapestry—a sixteenth-century Flemish work depicting the siege of a fortified coastal ______ would require at least three years of painstaking thread-by-thread restoration before it could be safely exhibited under controlled lighting conditions.', $lyceon_json$[{"key":"A","text":"city—would"},{"key":"B","text":"city, would"},{"key":"C","text":"city; would"},{"key":"D","text":"city would"}]$lyceon_json$::jsonb, 'A', NULL, E'The parenthetical appositive ''a sixteenth-century Flemish work depicting the siege of a fortified coastal city'' is opened with a dash after ''tapestry.'' To maintain punctuation symmetry, the parenthetical must close with a matching dash before the verb ''would require.'' Using a comma to close a dash-opened parenthetical creates mismatched delimiters, which violates standard conventions. A semicolon after ''city'' would incorrectly split the subject ''the textile conservator'' from its verb ''determined'' by severing the interior of the noun clause, and the clause beginning with ''would'' cannot stand alone as an independent clause. Omitting punctuation entirely leaves the dash-opened parenthetical unclosed, obscuring where the appositive ends and the predicate resumes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24A327Q', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the central claim of the text?', E'Literary scholar Priya Nagarajan has challenged the widespread view that the Urdu ghazal tradition declined in aesthetic quality after the 1857 Indian Rebellion. Critics have long pointed to the post-rebellion ghazals'' increasing reliance on political themes and explicit social commentary as evidence of artistic deterioration, arguing that the form''s classical conventions—intricate wordplay, layered metaphor, and strict prosodic discipline—were sacrificed for didactic immediacy. Nagarajan contends, however, that this assessment reflects a nostalgic bias toward Mughal-era courtly aesthetics rather than an objective literary evaluation. She demonstrates that poets such as Altaf Husain Hali and Muhammad Iqbal innovated within the ghazal''s formal constraints, repurposing traditional imagery of the beloved and the garden to encode critiques of colonial governance while preserving—and in some cases extending—the form''s metrical complexity. What earlier critics read as a degradation of the ghazal, Nagarajan argues, was in fact a transformation that expanded the genre''s expressive range without abandoning its technical foundations.', $lyceon_json$[{"key":"A","text":"Post-rebellion Urdu ghazal poets adapted classical formal conventions to address political subjects, and the perceived decline in quality reflects critical bias rather than genuine artistic loss."},{"key":"B","text":"The Urdu ghazal tradition was most artistically accomplished during the Mughal era, when poets adhered strictly to classical prosodic rules."},{"key":"C","text":"Altaf Husain Hali and Muhammad Iqbal abandoned the ghazal's traditional imagery in favor of explicit political messaging that appealed to wider audiences."},{"key":"D","text":"Nagarajan's research demonstrates that literary critics should evaluate poetry primarily on the basis of its political significance rather than its formal properties."}]$lyceon_json$::jsonb, 'A', NULL, E'Nagarajan''s central claim is that post-rebellion ghazal poets innovated within the form''s constraints to address political themes, and that the supposed decline represents critical bias favoring Mughal-era aesthetics rather than actual artistic deterioration. The choice capturing both the adaptation and the bias diagnosis reflects this accurately. The choice asserting Mughal-era superiority represents precisely the view Nagarajan opposes; it captures only the position she is refuting, not her own claim. The choice about Hali and Iqbal abandoning traditional imagery contradicts the passage, which states they repurposed traditional imagery rather than discarding it. The choice about evaluating poetry primarily by political significance misrepresents Nagarajan, who argues for recognizing that political content coexisted with formal mastery—not that political value should supersede formal evaluation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
