INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27Z75R3', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Philosopher Kwasi Wiredu contended that the uncritical adoption of European philosophical frameworks by African scholars ______ indigenous modes of reasoning, not by directly attacking them but by establishing foreign conceptual categories as the default vocabulary for academic discourse, thereby rendering local traditions inexpressible within the institutions that controlled knowledge production.', $lyceon_json$[{"key":"A","text":"marginalized"},{"key":"B","text":"plagiarized"},{"key":"C","text":"synthesized"},{"key":"D","text":"chronicled"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how adopting European frameworks pushed indigenous reasoning to the periphery by making foreign categories the default, rendering local traditions inexpressible in academic settings. The word meaning to relegate to a position of lesser importance captures this process of displacement through institutional dominance. The word meaning to present another''s work as one''s own describes intellectual theft, but the passage discusses systemic displacement of traditions, not copying them. The word meaning to combine elements into a coherent whole suggests blending traditions, but the passage describes one framework crowding out another, not merging them. The word meaning to record events in order describes documentation, which is unrelated to the displacement process the passage describes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D1FSXC', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'The 19th-century cartographer Elspeth Torrance was known for her refusal to ______ the boundaries of disputed territories on her maps; instead, she left such regions deliberately unmarked, arguing that presenting contested claims as settled fact was a form of political endorsement that no mapmaker should undertake.', $lyceon_json$[{"key":"A","text":"delineate"},{"key":"B","text":"traverse"},{"key":"C","text":"adjudicate"},{"key":"D","text":"commemorate"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a cartographer who refused to draw the boundaries of disputed territories, leaving them unmarked. The word meaning to describe or portray with precision, especially by drawing lines, directly captures the act of rendering boundaries on a map. The word meaning to travel across describes physical movement through a region, not the act of drawing it on a map. The word meaning to make a formal judgment on a dispute describes a legal or arbitrative function; while related to disputes, the passage concerns drawing boundaries, not ruling on them. The word meaning to honor or preserve the memory of describes memorialization, which is unrelated to the cartographic act being discussed.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
