INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EJ0RSO', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'When the bacterium Deinococcus radiodurans was first isolated from a can of irradiated ground meat in 1956, researchers assumed it was merely a laboratory curiosity. Subsequent experiments revealed that the organism could survive radiation doses three thousand times greater than what would kill a human, along with extreme desiccation, vacuum conditions, and acid baths. Scientists eventually discovered that Deinococcus achieves this resilience not through a single mechanism but through an interlocking suite of adaptations: redundant copies of its genome, an unusually efficient DNA repair system, and a dense arrangement of manganese antioxidants that protect its repair proteins from radiation damage.', $lyceon_json$[{"key":"A","text":"It introduces an organism's discovery, catalogues its extreme survival capabilities, and then explains the biological mechanisms underlying those capabilities."},{"key":"B","text":"It presents a scientific debate about the classification of an unusual bacterium and traces how that debate was eventually resolved."},{"key":"C","text":"It describes an experimental failure and then explains how researchers redesigned their methods to achieve a successful result."},{"key":"D","text":"It compares the radiation tolerance of several organisms and argues that one is superior to the others."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage proceeds in three stages: discovering the bacterium in irradiated meat (discovery), demonstrating it survives radiation, desiccation, vacuum, and acid (cataloguing capabilities), and identifying the redundant genome, DNA repair system, and manganese antioxidants responsible (explaining mechanisms). The option about a classification debate is unsupported; the passage never discusses taxonomic disagreement. The option about experimental failure mischaracterizes the passage; the initial assumption that the bacterium was a curiosity was not a failed experiment but an underestimation later corrected by further research. The option about comparing several organisms is inaccurate because the passage discusses only Deinococcus radiodurans and mentions no other species'' radiation tolerance.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2G5TMHJ', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the lead vocalist nor the three backup singers in the ensemble ______ willing to perform the newly arranged version of the anthem without at least two additional rehearsals.', $lyceon_json$[{"key":"A","text":"was"},{"key":"B","text":"were"},{"key":"C","text":"has been"},{"key":"D","text":"is"}]$lyceon_json$::jsonb, 'B', NULL, E'In a ''neither... nor...'' construction, the verb agrees with the subject nearest to it. Because ''the three backup singers'' is plural and is the element closest to the verb, the plural past tense ''were'' is required. The singular ''was'' would incorrectly agree with ''the lead vocalist'' rather than with the nearer plural subject. The singular present perfect ''has been'' fails on both number agreement and tense, since it does not agree with the plural nearer subject and introduces a tense inconsistent with the past-tense context. The singular present ''is'' likewise fails on number and uses present tense, which does not match the past-tense framing of the passage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GQ0032', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'In 1971, psychologist Philip Zimbardo proposed that the anonymity afforded by urban environments contributes to antisocial behavior—a hypothesis he tested by leaving abandoned cars in New York City and Palo Alto, California. The New York car was stripped within hours, while the Palo Alto car sat untouched for a week. Zimbardo interpreted this as evidence for his theory, but subsequent researchers have questioned whether the comparison was valid. Urban ecologist Maren Dietrich has argued that the cars differed in visible condition—the New York vehicle had its hood raised and license plates removed—and that these cues of prior vandalism, not anonymity per se, likely triggered the divergent outcomes. Dietrich''s reinterpretation aligns with the "broken windows" framework, which holds that signs of disorder invite further disorder regardless of population density.', $lyceon_json$[{"key":"A","text":"Zimbardo's abandoned-car experiment has been reinterpreted as reflecting cues of disorder rather than urban anonymity as the driver of antisocial behavior."},{"key":"B","text":"The broken windows framework has been conclusively validated by Dietrich's reanalysis of Zimbardo's 1971 study."},{"key":"C","text":"Zimbardo's 1971 experiment demonstrated that antisocial behavior is more prevalent in large cities than in small towns."},{"key":"D","text":"Dietrich's work primarily criticizes the ethical implications of Zimbardo's experimental design rather than its conclusions."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes Zimbardo''s original experiment and interpretation, then presents Dietrich''s reinterpretation that the visible condition of the cars—not urban anonymity—drove the different outcomes. The choice identifying this reinterpretation as the central point captures both the original claim and its revision. The choice claiming conclusive validation overstates the passage, which says Dietrich''s view "aligns with" the broken windows framework but does not declare it proven. The choice about antisocial behavior being more prevalent in cities reflects Zimbardo''s original interpretation, which the passage frames as contested rather than established. The choice about ethical criticism mischaracterizes Dietrich''s objection, which targets the experiment''s methodology and interpretation, not its ethics.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HKW676', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Historian Fatou Diagne has argued that the decline of trans-Saharan caravan routes in the sixteenth century was driven primarily by the expansion of Portuguese maritime trade along the West African coast, which offered faster and cheaper transport of gold and salt. ______ recent analysis of Ottoman customs ledgers from Tripoli suggests that overland trade volumes actually increased between 1540 and 1590, as the Ottoman conquest of North African ports created new demand for Sahelian goods that maritime routes did not efficiently serve.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"Moreover,"},{"key":"C","text":"Granted,"},{"key":"D","text":"On the contrary,"}]$lyceon_json$::jsonb, 'D', NULL, E'The first sentence presents Diagne''s argument that trans-Saharan trade declined due to Portuguese maritime competition. The second sentence introduces Ottoman customs data showing that overland trade volumes actually increased during the same period, directly contradicting Diagne''s claim. The transition "On the contrary" correctly signals that the evidence in the second sentence opposes the argument in the first. The option "In other words" implies the second sentence is a restatement of the first, but the customs data challenges rather than restates the decline thesis. The option "Moreover" signals additional supporting information, yet the second sentence undermines rather than builds on the original argument. The option "Granted" implies the second sentence concedes a point before the passage goes on to reassert the original claim, but no such reassertion follows; the customs evidence is presented as a substantive challenge, not a temporary concession.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IMJC8X', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The interdisciplinary research team, which had originally been assembled to study volcanic soil chemistry and which, after receiving an unexpected grant extension from the European Geosciences ______ redirected its focus toward measuring trace-element migration in subglacial aquifers, published its preliminary dataset in a peer-reviewed journal last March.', $lyceon_json$[{"key":"A","text":"Union, redirected"},{"key":"B","text":"Union redirected"},{"key":"C","text":"Union; redirected"},{"key":"D","text":"Union. Redirected"}]$lyceon_json$::jsonb, 'A', NULL, E'This sentence has a deeply nested structure: the main clause (''The interdisciplinary research team... published its preliminary dataset...'') contains a nonrestrictive relative clause (''which had originally been assembled... and which... redirected its focus...''), and within that relative clause, a parenthetical adverbial phrase (''after receiving an unexpected grant extension from the European Geosciences Union'') is set off by commas. Because this parenthetical opens with a comma after the second ''which,'' it must close with a comma after ''Union'' so that the relative clause can continue with ''redirected.'' Omitting the closing comma leaves the parenthetical unresolved and obscures the grammatical structure of the relative clause. A semicolon would fragment the interior of the relative clause at an inappropriate point, since ''redirected its focus'' is not an independent clause. A period after ''Union'' would sever the relative clause from the main clause entirely, producing a fragment beginning with ''Redirected'' that has no subject or grammatical connection to the rest of the sentence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2J9SBGK', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief introduction to a presentation about ferrofluid for a physics class. The student wants to explain what ferrofluid is to classmates who have not encountered it before. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JHZ3DA', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologist Kaede Fujimoto found that juvenile hawksbill turtles in the Ogasawara Islands rely almost exclusively on a single species of sponge for nutrition during their first two years of life. ______ conservation groups working in the region have prioritized protecting the coral reefs where this sponge grows most abundantly.', $lyceon_json$[{"key":"A","text":"In contrast,"},{"key":"B","text":"Accordingly,"},{"key":"C","text":"Nonetheless,"},{"key":"D","text":"For instance,"}]$lyceon_json$::jsonb, 'B', NULL, E'The second sentence describes conservation groups taking action that logically follows from the finding in the first sentence: because the turtles depend on one sponge species, groups prioritize protecting that sponge''s habitat. The transition "Accordingly" correctly signals this cause-and-effect relationship. The option "In contrast" introduces an opposition that does not exist between the two sentences, since the conservation effort is a response to the dietary finding, not a contradiction of it. The option "Nonetheless" implies the second sentence occurs despite the first, but protecting the sponge habitat is consistent with, not contrary to, the discovery of the turtles'' dependence. The option "For instance" implies the second sentence is one example of a broader point made in the first, but the first sentence presents a specific finding, and the second sentence describes a resulting action rather than an illustrative case.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KLVFI0', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The fermentation process used to produce traditional miso paste requires careful temperature regulation over many ______ the resulting product can vary dramatically in flavor, color, and nutritional content depending on the specific strain of koji mold introduced at the outset.', $lyceon_json$[{"key":"A","text":"months, the"},{"key":"B","text":"months; the"},{"key":"C","text":"months. the"},{"key":"D","text":"months the"}]$lyceon_json$::jsonb, 'B', NULL, E'The text contains two independent clauses: ''The fermentation process... over many months'' and ''the resulting product can vary dramatically...'' Two independent clauses cannot be joined with only a comma, so the option placing a comma after ''months'' produces a comma splice. A semicolon correctly links the two closely related independent clauses without a coordinating conjunction. The option placing a period after ''months'' followed by a lowercase ''the'' violates the convention that the first word of a new sentence must be capitalized. Omitting all punctuation between the clauses creates a run-on sentence that fuses two independent clauses together with no separation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LWPHG2', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'After seventeen years of meticulous breeding, the horticulturist finally produced a strain of orchid that could ______ the frigid temperatures of northern Scotland, blooming reliably even when nighttime readings dipped below minus eight degrees Celsius.', $lyceon_json$[{"key":"A","text":"withstand"},{"key":"B","text":"anticipate"},{"key":"C","text":"regulate"},{"key":"D","text":"circumvent"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes an orchid that blooms reliably despite frigid temperatures, indicating the plant can endure or tolerate extreme cold. The word meaning to endure without being adversely affected fits this context precisely. The word meaning to expect or predict describes foresight, not physical resilience to cold. The word meaning to control or adjust describes managing a system, not surviving harsh conditions. The word meaning to find a way around describes avoidance, but the orchid is not avoiding the cold — it is thriving in it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M0GDSF', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Volcanic glass, known as obsidian, fractures along curved surfaces to produce edges sharper than modern surgical scalpels. Archaeological evidence shows that obsidian tools were traded across distances exceeding 800 kilometers in Neolithic Anatolia, far beyond the material''s volcanic source regions. Because obsidian from different volcanic flows has a distinct chemical signature detectable through X-ray fluorescence analysis, researchers can match artifacts found at settlement sites to specific source volcanoes. This capability suggests that ________', $lyceon_json$[{"key":"A","text":"ancient trade networks can be mapped with considerable geographic precision by analyzing the chemical composition of obsidian artifacts."},{"key":"B","text":"obsidian was valued primarily for its visual appearance rather than its functional properties as a cutting tool."},{"key":"C","text":"X-ray fluorescence analysis was originally developed for archaeological applications before being adopted by other scientific fields."},{"key":"D","text":"Neolithic communities in Anatolia lacked access to alternative materials suitable for manufacturing cutting tools."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that obsidian has chemically distinct signatures traceable to specific volcanoes and that artifacts traveled hundreds of kilometers from their sources. The logical conclusion is that these traceable signatures allow researchers to reconstruct ancient trade routes with geographic precision. The choice about visual appearance contradicts the passage''s emphasis on obsidian''s functional sharpness and introduces an unsupported claim. The choice about the origins of X-ray fluorescence makes a historical claim about the technology''s development that the passage never addresses. The choice about lacking alternative materials is unsupported—the passage notes obsidian was traded widely but says nothing about the availability of other tool-making materials.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M3FSS3', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Having spent nearly eleven years cataloging the acoustic signatures of over forty species of bats across the limestone karst formations of northern ______ the behavioral ecologist Dr. Priya Venkatesh compiled a database that researchers worldwide now use to identify bat species by their echolocation frequencies alone.', $lyceon_json$[{"key":"A","text":"Laos,"},{"key":"B","text":"Laos."},{"key":"C","text":"Laos;"},{"key":"D","text":"Laos"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence opens with a participial phrase (''Having spent nearly eleven years cataloging... northern Laos'') that modifies the subject ''the behavioral ecologist Dr. Priya Venkatesh.'' A comma is the only correct punctuation to separate an introductory participial phrase from the main clause it modifies. Placing a period after ''Laos'' would sever the participial phrase from the main clause, creating a sentence fragment that lacks both a subject and a finite verb. A semicolon requires independent clauses on both sides, but the participial phrase is not an independent clause. Omitting punctuation entirely fuses the introductory phrase into the main clause without the required grammatical pause, creating a confusing run-on.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MRHKPS', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Historian Claudia Rennert has examined seventeenth-century Dutch guild records to study how master painters managed their workshops. Rennert found that contracts between masters and apprentices frequently specified which portions of a commissioned painting each party would execute: masters typically reserved faces and hands for themselves while delegating drapery, backgrounds, and architectural elements to senior apprentices. Interestingly, the contracts also reveal that clients were generally aware of and consented to this division of labor, often negotiating reduced fees when a greater proportion of the work would be completed by apprentices. Rennert argues that this evidence challenges the modern assumption that ________', $lyceon_json$[{"key":"A","text":"seventeenth-century Dutch paintings attributed to a single master were understood by contemporary buyers as collaborative products whose value was openly calibrated to the master's degree of personal involvement."},{"key":"B","text":"apprentices in Dutch painting workshops rarely developed the technical proficiency needed to work independently after completing their training."},{"key":"C","text":"the commercial art market in the seventeenth-century Dutch Republic was less economically significant than markets for other luxury goods such as textiles or ceramics."},{"key":"D","text":"modern art historians have generally overestimated the number of paintings produced by seventeenth-century Dutch workshops."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how clients knew about and negotiated prices around the division of labor between masters and apprentices. Rennert''s argument challenges the modern assumption that single-master attribution implied sole authorship. The logical completion is that contemporary buyers understood these paintings as collaborative products and adjusted the price accordingly. The choice about apprentices lacking proficiency contradicts the passage''s implication that apprentices were trusted with significant portions of paintings. The choice about the commercial art market''s relative economic significance introduces a comparison the passage never addresses. The choice about overestimating painting output concerns quantity rather than the authorship question central to Rennert''s argument.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NCMIQX', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding, if true, would most directly undermine the explanation proposed by Whitfield and Cabrera?', E'Ecologists Whitfield and Cabrera have proposed that the rapid expansion of white-tailed deer populations in the northeastern United States since the 1990s is primarily attributable to the regional decline of eastern coyote populations caused by sarcoptic mange outbreaks. They argue that reduced coyote predation on deer fawns during their first six weeks of life—the period of highest vulnerability—removed a critical population bottleneck, allowing deer herds to grow unchecked. Other researchers have noted, however, that deer population increases have also occurred in regions where coyote numbers remained stable, suggesting that additional factors may be involved.', $lyceon_json$[{"key":"A","text":"In regions where sarcoptic mange reduced coyote populations by more than 60 percent, fawn survival rates during the first six weeks of life did not increase significantly compared to pre-outbreak levels."},{"key":"B","text":"White-tailed deer in the northeastern United States have shifted their foraging patterns over the past three decades, increasingly feeding on agricultural crops rather than forest browse."},{"key":"C","text":"Eastern coyotes that survived sarcoptic mange outbreaks developed partial immunity, and their offspring showed lower susceptibility to the disease in subsequent generations."},{"key":"D","text":"Suburban development in the northeastern United States has created edge habitat that favors white-tailed deer by providing both cover and abundant herbaceous forage."}]$lyceon_json$::jsonb, 'A', NULL, E'Whitfield and Cabrera''s explanation hinges on the claim that reduced coyote predation increased fawn survival during the critical first six weeks. A finding that fawn survival rates did not actually increase in areas where coyote populations collapsed would directly sever this causal link, undermining the core mechanism they propose. The finding about deer shifting to agricultural foraging describes a behavioral change but does not address whether coyote decline caused population growth. The finding about coyote immunity concerns the long-term trajectory of mange but does not challenge the claim that reduced predation increased fawn survival during the period of coyote decline. The finding about suburban edge habitat offers an alternative explanation for deer population growth, but providing an alternative does not directly undermine the specific mechanism Whitfield and Cabrera propose—it merely supplements the point already noted by other researchers in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ONMWYP', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a research summary about the 2022 volcanic eruption of Hunga Tonga-Hunga Ha''apai for a geology seminar. The student wants to present the eruption''s atmospheric effects while acknowledging scientific uncertainty about its long-term climatic implications. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Q6MNDG', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the final sentence in the text?', E'In her 2021 monograph, musicologist Thea Kronberg argued that the standard periodization of Western classical music — Baroque, Classical, Romantic, Modern — imposes artificial boundaries on what were in fact gradual and overlapping stylistic transitions. She demonstrated that composers routinely classified as belonging to a single period employed techniques associated with both earlier and later periods throughout their careers. Kronberg acknowledged, however, that abandoning periodization entirely would leave scholars without a shared vocabulary for situating composers in historical context, a practical consequence she described as ''trading false precision for genuine incoherence.''', $lyceon_json$[{"key":"A","text":"It concedes a practical limitation of the position argued in the preceding sentences, using a quotation to characterize the tradeoff involved."},{"key":"B","text":"It introduces a new argument that contradicts the thesis presented earlier in the passage."},{"key":"C","text":"It provides an additional example that reinforces the claim that periodization boundaries are artificial."},{"key":"D","text":"It summarizes the methodology Kronberg used to analyze composers' stylistic techniques across periods."}]$lyceon_json$::jsonb, 'A', NULL, E'The final sentence begins with ''Kronberg acknowledged, however,'' signaling a concession. She admits that eliminating periodization would remove a shared scholarly vocabulary, a practical cost she characterizes with the quoted phrase ''trading false precision for genuine incoherence.'' This concedes a limitation of her own critique rather than abandoning it. The option about introducing a contradictory argument overstates the concession; Kronberg acknowledges a practical difficulty with her position, not a refutation of it. The option about providing an additional example of artificial boundaries misidentifies the sentence''s function; it discusses the consequences of removing boundaries, not further evidence that they are artificial. The option about summarizing methodology is inaccurate; the sentence addresses a practical tradeoff, not research methods.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
