INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2REFMHU', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Computational linguist Yael Shimoni has analyzed a corpus of 14,000 nineteenth-century American newspaper editorials to study how metaphorical language about economic systems changed during periods of financial crisis. Shimoni found that during stable periods, editorials predominantly employed organic metaphors—describing the economy as "growing," "healthy," or "bearing fruit"—which frame economic activity as a natural process subject to cyclical rhythms. During financial panics, however, editors shifted sharply toward mechanical metaphors—the economy was "broken," "derailed," or in need of "repair"—which frame economic activity as an engineered system susceptible to discrete malfunctions. Shimoni notes that the mechanical framing implicitly assigns agency and blame in ways the organic framing does not: while a plant that fails to thrive invites questions about environmental conditions, a machine that breaks down invites questions about its operators. This pattern suggests that ________', $lyceon_json$[{"key":"A","text":"the shift to mechanical metaphors during crises functioned rhetorically to construct economic downturns as failures of human management rather than as inevitable features of a naturally fluctuating system."},{"key":"B","text":"nineteenth-century American newspaper editors consciously coordinated their metaphorical language to influence public policy responses to financial panics."},{"key":"C","text":"organic metaphors are inherently more accurate descriptions of economic systems than mechanical metaphors because economies exhibit cyclical patterns similar to biological organisms."},{"key":"D","text":"the prevalence of mechanical metaphors in crisis-period editorials reflected editors' growing familiarity with industrial technology rather than any shift in economic reasoning."}]$lyceon_json$::jsonb, 'A', NULL, E'Shimoni''s analysis establishes that mechanical metaphors assign agency and blame by framing economic problems as breakdowns requiring an operator at fault, whereas organic metaphors normalize downturns as natural cycles. The logical conclusion is that the crisis-period shift to mechanical metaphors rhetorically reframed downturns as human failures rather than natural phenomena. The choice about conscious coordination among editors introduces a claim about deliberate conspiracy that goes well beyond the observed pattern of metaphor usage. The choice about organic metaphors being inherently more accurate introduces an evaluative claim about which metaphor type is correct, whereas Shimoni''s analysis is descriptive, examining how metaphors function rhetorically. The choice attributing the shift to familiarity with industrial technology offers a plausible alternative explanation for the metaphor change but ignores Shimoni''s specific finding about how the mechanical framing assigns agency and blame—the rhetorical function, not merely the source domain, is the key analytical point.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2S9DIZR', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing an article about Wangari Maathai''s Green Belt Movement for an environmental studies course. The student wants to emphasize how the movement connected environmental restoration with women''s economic empowerment. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TEW8BJ', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Displayed prominently in the east wing of the newly renovated provincial museum ______ a pair of obsidian ceremonial blades and a fragmentary clay vessel, all recovered from a burial site that archaeologists believe dates to the seventh century BCE.', $lyceon_json$[{"key":"A","text":"is"},{"key":"B","text":"are"},{"key":"C","text":"has been"},{"key":"D","text":"was"}]$lyceon_json$::jsonb, 'B', NULL, E'This sentence uses inverted word order: the participial phrase ''Displayed prominently in the east wing of the newly renovated provincial museum'' precedes the verb, and the true compound subject—''a pair of obsidian ceremonial blades and a fragmentary clay vessel''—follows it. Because the compound subject refers to multiple items joined by ''and,'' the verb must be plural. The phrase ''newly renovated'' and the present-tense context of museum display indicate that the present tense is appropriate. The singular present ''is'' fails to agree with the compound subject. The singular present perfect ''has been'' is likewise singular and introduces an aspectual distinction (completed action with present relevance) that does not fit the description of an ongoing display. The singular past ''was'' fails on both number agreement and tense, since the subject is plural and the artifacts are currently on display.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TN2DIB', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the purpose of the text?', E'The rufous hummingbird migrates up to 3,900 miles between its breeding grounds in the Pacific Northwest and its wintering habitat in Mexico. Researchers tracking these birds with lightweight radio transmitters have found that individual hummingbirds return to the same specific shrubs and feeders along their route year after year, sometimes arriving within a two-day window of their previous year''s visit.', $lyceon_json$[{"key":"A","text":"To describe a notable behavior of rufous hummingbirds during migration and present research findings that illustrate it."},{"key":"B","text":"To argue that rufous hummingbirds should be classified as endangered due to their demanding migration."},{"key":"C","text":"To compare the migration patterns of rufous hummingbirds with those of other hummingbird species."},{"key":"D","text":"To explain the technology researchers use to study bird migration routes."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage introduces the rufous hummingbird''s long migration and then presents research findings about individuals returning to the same specific stops with remarkable temporal precision. This structure describes a notable behavior and supports it with research evidence. The option about arguing for endangered classification introduces an advocacy purpose absent from the text, which makes no conservation claims. The option about comparing species is unsupported because the passage discusses only the rufous hummingbird and mentions no other species. The option about explaining tracking technology misidentifies the focus; radio transmitters are mentioned briefly as a method, but the passage centers on the birds'' behavior, not the equipment.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2V0RTCL', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Cognitive scientist Renata Olszewska has proposed that bilingual individuals experience less age-related cognitive decline because switching between languages exercises executive control functions in the prefrontal cortex. Her team''s 2023 longitudinal study of 1,400 Polish-German bilingual adults found measurably slower rates of decline in task-switching performance compared to monolingual peers. ______ a reanalysis of Olszewska''s data by a team at the University of Edinburgh revealed that when socioeconomic status and educational attainment were more rigorously controlled, the bilingual advantage in task-switching narrowed to a statistically nonsignificant margin, raising questions about whether language switching itself or the broader cognitive enrichment associated with bilingualism drives the observed effect.', $lyceon_json$[{"key":"A","text":"That said,"},{"key":"B","text":"In fact,"},{"key":"C","text":"Along these lines,"},{"key":"D","text":"Specifically,"}]$lyceon_json$::jsonb, 'A', NULL, E'The first two sentences establish Olszewska''s hypothesis and supporting evidence. The final sentence introduces a reanalysis that complicates her findings by showing the bilingual advantage may be confounded by socioeconomic factors, qualifying but not entirely negating the original claim. The transition "That said" correctly signals a concessive turn: the passage acknowledges the earlier evidence and then introduces a complication. The option "In fact" typically intensifies or confirms a preceding point, but the reanalysis weakens rather than strengthens the original finding. The option "Along these lines" signals that the following sentence extends or parallels the preceding argument, yet the reanalysis challenges rather than reinforces Olszewska''s conclusion. The option "Specifically" implies the final sentence is a narrower elaboration of the preceding claim, but the reanalysis introduces a methodological critique from an independent team rather than specifying a detail within Olszewska''s own study.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YR4ZNP', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The municipal water authority has recommended that every residential property owner whose plumbing predates the 1987 lead-abatement ordinance ______ a certified inspector to evaluate the condition of all service lines connecting the dwelling to the municipal main.', $lyceon_json$[{"key":"A","text":"hires"},{"key":"B","text":"hire"},{"key":"C","text":"will hire"},{"key":"D","text":"should hire"}]$lyceon_json$::jsonb, 'B', NULL, E'The verb ''recommended'' triggers the mandative subjunctive in the ''that'' clause that follows it. In Standard English, verbs of recommendation, demand, and insistence take the subjunctive mood in their complement clauses, which requires the bare infinitive (base form) of the verb regardless of the subject''s number. Although ''every residential property owner'' is grammatically singular and would ordinarily take the indicative ''hires,'' the subjunctive demands the uninflected form ''hire.'' The option using ''will hire'' incorrectly inserts a future-tense modal into the subjunctive construction, which is not permitted after verbs of recommendation. The option using ''should hire'' introduces a modal that, while sometimes acceptable in British English as an alternative to the subjunctive, is not the standard American English convention tested on the SAT and adds an unnecessary layer of conditionality.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Z07QPK', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Tromsø have discovered that Arctic cod (Boreogadus saida) can survive in waters as cold as -1.8 degrees Celsius thanks to antifreeze glycoproteins circulating in their blood. These specialized proteins bind to nascent ice crystals forming within the fish''s body, preventing the crystals from growing large enough to damage cell membranes. The glycoproteins are produced year-round, not just during winter months, which suggests that the fish maintain a constant biochemical readiness for freezing conditions rather than mounting a seasonal response.', $lyceon_json$[{"key":"A","text":"Arctic cod produce antifreeze glycoproteins that prevent lethal ice crystal growth, and this defense operates continuously rather than seasonally."},{"key":"B","text":"Scientists in Tromsø have pioneered new methods for studying how marine organisms adapt to polar environments."},{"key":"C","text":"The cell membranes of Arctic cod are structurally distinct from those of temperate fish species."},{"key":"D","text":"Antifreeze glycoproteins found in Arctic cod could be synthesized in laboratories for use in organ preservation technology."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on how Arctic cod survive subfreezing waters through antifreeze glycoproteins that inhibit ice crystal growth, emphasizing that this defense is maintained year-round. The choice stating that these proteins prevent lethal ice crystal growth and operate continuously captures both key points. The choice about scientists pioneering new methods misrepresents the passage, which describes a finding about fish biology rather than methodological innovation. The choice about structurally distinct cell membranes introduces a claim never made in the passage. The choice about laboratory synthesis for organ preservation extends far beyond anything discussed in the text.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
